/**
 * Server-side live sync coordinator.
 * Listens for livesync/change messages from editors via comms,
 * translates them into patchFlows() calls, and broadcasts results.
 * Non-baton-holders' changes are queued as proposals for the holder to accept.
 */

let runtime;
let batonOpts = null;
const proposals = new Map(); // proposalId -> { changes, commsSession, user, changeId, timestamp }
let proposalCounter = 0;

/**
 * Escalate a non-holder change to a proposal that the baton holder
 * must accept or reject.
 */
function escalateToProposal(data, commsSession, senderMpSession, user) {
    var proposalId = 'prop_' + (++proposalCounter) + '_' + Date.now();
    proposals.set(proposalId, {
        changes: data.changes,
        commsSession: commsSession,
        senderMpSession: senderMpSession,
        user: user,
        changeId: data.changeId,
        timestamp: Date.now()
    });

    // Acknowledge to proposer that it needs approval
    runtime.events.emit('comms', {
        topic: 'livesync/proposal-pending',
        data: {
            proposalId: proposalId,
            changeId: data.changeId
        },
        session: commsSession
    });

    // Forward to baton holder
    var holderComms = batonOpts && batonOpts.getBatonHolderComms
        ? batonOpts.getBatonHolderComms()
        : null;
    if (holderComms) {
        runtime.events.emit('comms', {
            topic: 'livesync/proposal',
            data: {
                proposalId: proposalId,
                changes: data.changes,
                user: user,
                changeId: data.changeId
            },
            session: holderComms
        });
    }

    runtime.log.trace('livesync proposal escalated proposalId:' + proposalId +
        ' changeId:' + (data.changeId || 'unknown') +
        ' from:' + (senderMpSession || 'unknown'));
}

module.exports = {
    init: function(_runtime, _batonOpts) {
        runtime = _runtime;
        batonOpts = _batonOpts || null;

        runtime.events.on('comms:message:livesync/change', async function(opts) {
            const session = opts.session;
            const user = opts.user;
            const data = opts.data;

            if (!data || !data.changes || !Array.isArray(data.changes)) {
                runtime.events.emit('comms', {
                    topic: 'livesync/error',
                    data: {
                        changeId: data && data.changeId,
                        error: 'Invalid change payload'
                    },
                    session: session
                });
                return;
            }

            // Baton gate: non-holders' changes become proposals
            if (batonOpts && batonOpts.getBatonHolder) {
                var holderSession = batonOpts.getBatonHolder();
                if (holderSession) {
                    var senderSession = batonOpts.getSessionForComms
                        ? batonOpts.getSessionForComms(session)
                        : null;
                    if (senderSession && senderSession !== holderSession) {
                        // Non-holder: try to auto-apply. patchFlows applies
                        // config changes in-place, so we only escalate if it
                        // throws entirely (fundamental error). Partial runtime
                        // failures (e.g. a node failing to start) are included
                        // in the broadcast so clients can see them.
                        try {
                            var autoResult = await runtime.flows.patchFlows(data.changes, user);

                            // Broadcast to everyone — includes any per-node
                            // failures in results so UIs can flag them
                            runtime.events.emit('comms', {
                                topic: 'livesync/applied',
                                data: {
                                    changeId: data.changeId,
                                    session: session,
                                    senderMpSession: senderSession,
                                    rev: autoResult.rev,
                                    changes: data.changes,
                                    results: autoResult.results
                                }
                            });

                            runtime.log.trace('livesync auto-applied (non-holder) changeId:' +
                                (data.changeId || 'unknown') +
                                ' changes:' + data.changes.length +
                                ' failed:' + (autoResult.results.failed ? autoResult.results.failed.length : 0));

                        } catch(err) {
                            // patchFlows threw — config was not applied,
                            // escalate to baton holder for manual review
                            escalateToProposal(data, session, senderSession, user);
                        }
                        return;
                    }
                }
            }

            // Baton holder (or no baton system) — apply directly
            try {
                var result = await runtime.flows.patchFlows(data.changes, user);

                // Broadcast success to ALL editors
                runtime.events.emit('comms', {
                    topic: 'livesync/applied',
                    data: {
                        changeId: data.changeId,
                        session: session,
                        rev: result.rev,
                        changes: data.changes,
                        results: result.results
                    }
                });

                runtime.log.trace('livesync applied changeId:' + (data.changeId || 'unknown') +
                    ' changes:' + data.changes.length +
                    ' success:' + result.results.success.length +
                    ' failed:' + result.results.failed.length);

            } catch(err) {
                runtime.events.emit('comms', {
                    topic: 'livesync/error',
                    data: {
                        changeId: data.changeId,
                        error: err.message
                    },
                    session: session
                });

                runtime.log.warn('livesync error changeId:' + (data.changeId || 'unknown') +
                    ' error:' + err.message);
            }
        });

        // --- Proposal accept/reject handlers ---

        runtime.events.on('comms:message:livesync/proposal-accept', async function(opts) {
            var proposalId = opts.data && opts.data.proposalId;
            var proposal = proposals.get(proposalId);
            if (!proposal) return;

            // Verify sender is the baton holder
            if (batonOpts && batonOpts.getBatonHolder && batonOpts.getSessionForComms) {
                var senderMp = batonOpts.getSessionForComms(opts.session);
                if (senderMp !== batonOpts.getBatonHolder()) return;
            }

            proposals.delete(proposalId);

            try {
                var result = await runtime.flows.patchFlows(proposal.changes, proposal.user);

                // Broadcast to ALL editors (including proposer and holder)
                runtime.events.emit('comms', {
                    topic: 'livesync/applied',
                    data: {
                        changeId: proposal.changeId,
                        session: proposal.commsSession,
                        senderMpSession: proposal.senderMpSession,
                        rev: result.rev,
                        changes: proposal.changes,
                        results: result.results
                    }
                });

                runtime.log.trace('livesync proposal accepted proposalId:' + proposalId +
                    ' changes:' + proposal.changes.length);

            } catch(err) {
                // Send error to the original proposer
                runtime.events.emit('comms', {
                    topic: 'livesync/error',
                    data: {
                        changeId: proposal.changeId,
                        error: err.message
                    },
                    session: proposal.commsSession
                });

                runtime.log.warn('livesync proposal apply failed proposalId:' + proposalId +
                    ' error:' + err.message);
            }
        });

        runtime.events.on('comms:message:livesync/proposal-reject', function(opts) {
            var proposalId = opts.data && opts.data.proposalId;
            var proposal = proposals.get(proposalId);
            if (!proposal) return;

            proposals.delete(proposalId);

            // Notify the proposer that their changes were rejected
            runtime.events.emit('comms', {
                topic: 'livesync/proposal-rejected',
                data: {
                    proposalId: proposalId,
                    changeId: proposal.changeId
                },
                session: proposal.commsSession
            });

            runtime.log.trace('livesync proposal rejected proposalId:' + proposalId);
        });
    }
};
